mapper.update:
UPDATE image_upload_tickets
SET status = 'VERIFYING'
WHERE ticket_id = #{ticketId}
  AND user_id = #{userId}
  AND status = 'ISSUED'
  AND expires_at >= #{now}

UPDATE image_upload_tickets
SET status = 'CONFIRMED', confirmed_at = #{confirmedAt}
WHERE ticket_id = #{ticketId} AND status = 'VERIFYING'

mapper.select:
SELECT ticket_id, user_id, object_key, expected_size, expected_format, expected_mime,
       status, expires_at, created_at, confirmed_at
FROM image_upload_tickets
WHERE status = 'ISSUED' AND expires_at < #{now}
ORDER BY expires_at
LIMIT #{limit}
